import"./chunk-VC46IEJQ.js";var e=(t,o,a,l,d,s,r,i,n)=>({name:{en:t[0],zh:t[1]},desc:{en:o[0],zh:o[1]},tour:{en:a[0],zh:a[1]},...n?{spoiler:{en:n[0],zh:n[1]}}:{},source:{confidence:l,refs:d,book:{en:s[0],zh:s[1]},unknown:{en:r[0],zh:r[1]},interpretation:{en:i[0],zh:i[1]}}}),h=["The books give no plan of the town.","\u4E66\u4E2D\u6CA1\u6709\u7ED9\u51FA\u57CE\u9547\u7684\u5E03\u5C40\u3002"],w={id:"selhorys",intro:{en:"A walled Volantene river town where the Selhoru joins the lower Rhoyne, on the river route between the upper Rhoyne and Volantis. The books say very little about it; this is a quiet, deliberately restrained scene.",zh:"\u585E\u5C14\u970D\u5229\u65AF\u662F\u74E6\u5170\u63D0\u65AF\u6CBB\u4E0B\u7684\u4E00\u5EA7\u8BBE\u9632\u6CB3\u9547\uFF0C\u5750\u843D\u5728\u585E\u5C14\u970D\u9C81\u6CB3\u6C47\u5165\u6D1B\u6069\u6CB3\u4E0B\u6E38\u4E4B\u5904\uFF0C\u627C\u5B88\u901A\u5F80\u74E6\u5170\u63D0\u65AF\u7684\u6CB3\u9053\u3002\u4E66\u4E2D\u7740\u58A8\u6781\u5C11\uFF0C\u672C\u573A\u666F\u6709\u610F\u4FDD\u6301\u514B\u5236\u3002"},notes:{en:"Established (mostly via wiki summaries of A Dance with Dragons): a walled Volantene town at the confluence of the Selhoru and the Rhoyne, with sandstone walls and shops, stalls and storehouses along the piers. Everything else is invented: the layout, buildings, boats and market.",zh:"\u53EF\u786E\u8BA4\u7684\u5185\u5BB9\uFF08\u4E3B\u8981\u6765\u81EA\u7EF4\u57FA\u5BF9\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u7684\u6458\u8981\uFF09\uFF1A\u4E00\u5EA7\u5C5E\u4E8E\u74E6\u5170\u63D0\u65AF\u7684\u8BBE\u9632\u57CE\u9547\uFF0C\u4F4D\u4E8E\u585E\u5C14\u970D\u9C81\u6CB3\u4E0E\u6D1B\u6069\u6CB3\u4EA4\u6C47\u5904\uFF0C\u6709\u7802\u5CA9\u57CE\u5899\uFF0C\u7801\u5934\u6CBF\u7EBF\u5206\u5E03\u7740\u5E97\u94FA\u3001\u644A\u6863\u4E0E\u4ED3\u5E93\u3002\u5176\u4F59\u5747\u4E3A\u81EA\u62DF\uFF1A\u5E03\u5C40\u3001\u5EFA\u7B51\u3001\u8239\u53EA\u4E0E\u96C6\u5E02\u3002"},tour:["confluence","piers","storehouses","sandstone-walls","river-gate","market-quarter"],sources:[{ref:"awoiaf",checked:"search-snippet",note:{en:"Walled Volantene town at the Selhoru\u2013Rhoyne confluence; sandstone walls; shops, stalls and storehouses along the piers: confirmed by a web-search summary; pages not fetched.",zh:"\u4F4D\u4E8E\u585E\u5C14\u970D\u9C81\u6CB3\u4E0E\u6D1B\u6069\u6CB3\u4EA4\u6C47\u5904\u7684\u74E6\u5170\u63D0\u65AF\u8BBE\u9632\u57CE\u9547\uFF1B\u7802\u5CA9\u57CE\u5899\uFF1B\u7801\u5934\u6CBF\u7EBF\u6709\u5E97\u94FA\u3001\u644A\u6863\u4E0E\u4ED3\u5E93\uFF1A\u7ECF\u7F51\u7EDC\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF0C\u672A\u80FD\u6253\u5F00\u9875\u9762\u3002"}},{ref:"adwd",checked:"search-snippet",note:{en:"A river boat's stop here in A Dance with Dragons (and the brothel scene in the spoiler) known only from search summaries; the text was not re-read.",zh:"\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\u4E00\u6761\u6CB3\u8239\u5728\u6B64\u505C\u9760\uFF08\u4EE5\u53CA\u5267\u900F\u4E2D\u7684\u5993\u9662\u60C5\u8282\uFF09\uFF0C\u4EC5\u636E\u641C\u7D22\u6458\u8981\u5F97\u77E5\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002"}}],landmarks:{confluence:e(["Confluence","\u6C47\u6D41\u5904"],["The Selhoru joins the Rhoyne here, widening the water into a busy reach.","\u585E\u5C14\u970D\u9C81\u6CB3\u5728\u6B64\u6C47\u5165\u6D1B\u6069\u6CB3\uFF0C\u6C34\u9762\u968F\u4E4B\u5F00\u9614\uFF0C\u8239\u6765\u8239\u5F80\u3002"],["Two rivers meet, and the town grew up where they join.","\u4E24\u6CB3\u5728\u6B64\u4EA4\u6C47\uFF0C\u57CE\u9547\u56E0\u4E4B\u800C\u5174\u3002"],"high",["adwd","awoiaf"],["The town stands where the Selhoru meets the lower Rhoyne.","\u57CE\u9547\u4F4D\u4E8E\u585E\u5C14\u970D\u9C81\u6CB3\u4E0E\u6D1B\u6069\u6CB3\u4E0B\u6E38\u7684\u4EA4\u6C47\u5904\u3002"],["The exact shape of the junction.","\u6C47\u6D41\u5904\u7684\u786E\u5207\u5F62\u72B6\u3002"],["A simplified Y-shaped junction.","\u7B80\u5316\u4E3A\u4E2B\u5B57\u5F62\u6C47\u6D41\u3002"]),piers:e(["Piers","\u7801\u5934"],["Wooden piers reach into the Rhoyne; river boats tie up alongside.","\u6728\u6808\u6865\u4F38\u5165\u6D1B\u6069\u6CB3\uFF0C\u6CB3\u8239\u5728\u65C1\u7CFB\u6CCA\u3002"],["River traffic calls here on the way to Volantis.","\u5F80\u6765\u74E6\u5170\u63D0\u65AF\u7684\u6CB3\u8239\u5728\u6B64\u505C\u9760\u3002"],"medium",["adwd","awoiaf"],["Shops, stalls and storehouses line the piers.","\u7801\u5934\u6CBF\u7EBF\u6392\u5217\u7740\u5E97\u94FA\u3001\u644A\u6863\u4E0E\u4ED3\u5E93\u3002"],["The number and form of the piers.","\u7801\u5934\u7684\u6570\u91CF\u4E0E\u5F62\u5236\u3002"],["A row of timber piers; invented.","\u4E00\u6392\u6728\u6808\u6865\uFF1B\u7CFB\u81EA\u62DF\u3002"],["In A Dance with Dragons the Shy Maid puts in here, and in a Selhorys brothel Ser Jorah Mormont seizes Tyrion.","\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\u4E2D\uFF0C\u201C\u7F9E\u6DA9\u5C11\u5973\u53F7\u201D\u5728\u6B64\u9760\u5CB8\uFF1B\u4E54\u62C9\xB7\u83AB\u5C14\u8499\u7235\u58EB\u5728\u585E\u5C14\u970D\u5229\u65AF\u7684\u4E00\u5BB6\u5993\u9662\u91CC\u64D2\u4F4F\u4E86\u63D0\u5229\u6602\u3002"]),storehouses:e(["Storehouses","\u4ED3\u5E93"],["Long plastered warehouses with tiled roofs stand behind the piers.","\u7801\u5934\u540E\u65B9\u662F\u4E00\u6392\u6392\u62B9\u7070\u74E6\u9876\u7684\u957F\u4ED3\u5E93\u3002"],["Goods bound up and down the river pass through here.","\u6CBF\u6CB3\u4E0A\u4E0B\u7684\u8D27\u7269\u5728\u6B64\u4E2D\u8F6C\u3002"],"medium",["awoiaf"],["Storehouses along the piers are mentioned in summaries.","\u6458\u8981\u63D0\u5230\u7801\u5934\u6CBF\u7EBF\u6709\u4ED3\u5E93\u3002"],["Size and appearance.","\u89C4\u6A21\u4E0E\u5916\u89C2\u3002"],["Six near-identical gabled warehouses; invented.","\u516D\u5EA7\u51E0\u4E4E\u4E00\u6837\u7684\u5C71\u5899\u4ED3\u5E93\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"sandstone-walls":e(["Sandstone Walls","\u7802\u5CA9\u57CE\u5899"],["A ring of warm sandstone walls and towers encloses the town.","\u6696\u8272\u7802\u5CA9\u57CE\u5899\u4E0E\u5854\u697C\u73AF\u7ED5\u5168\u9547\u3002"],["Sandstone walls guard a small town on a frontier river.","\u7802\u5CA9\u57CE\u5899\u5B88\u62A4\u7740\u8FD9\u5EA7\u8FB9\u5883\u6CB3\u7554\u7684\u5C0F\u9547\u3002"],"medium",["awoiaf"],["The town is walled in sandstone (summary).","\u57CE\u9547\u6709\u7802\u5CA9\u57CE\u5899\uFF08\u636E\u6458\u8981\uFF09\u3002"],["Height, circuit and towers.","\u9AD8\u5EA6\u3001\u5468\u957F\u4E0E\u5854\u697C\u3002"],["An oval ring about 11 m high; invented.","\u7EA611\u7C73\u9AD8\u7684\u692D\u5706\u5F62\u57CE\u5899\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"river-gate":e(["River Gate","\u6CB3\u95E8"],["A twin-towered gate pierces the wall where the road meets the river.","\u5927\u8DEF\u4E0E\u6CB3\u6D41\u76F8\u9047\u5904\uFF0C\u57CE\u5899\u4E0A\u5F00\u7740\u4E00\u5EA7\u53CC\u5854\u57CE\u95E8\u3002"],["Road and river meet at the gate.","\u5927\u8DEF\u4E0E\u6CB3\u6D41\u5728\u57CE\u95E8\u524D\u4EA4\u4F1A\u3002"],"low",["awoiaf"],["No gate is described in the sources checked.","\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u63D0\u53CA\u57CE\u95E8\u3002"],h,["Two plain gatehouses on a north\u2013south axis; invented.","\u5357\u5317\u8F74\u7EBF\u4E0A\u7684\u4E24\u5EA7\u6734\u7D20\u95E8\u697C\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"market-quarter":e(["Market Quarter","\u96C6\u5E02\u533A"],["Awnings and stalls before the gate, where river traders meet buyers from the countryside.","\u57CE\u95E8\u524D\u7684\u906E\u7BF7\u4E0E\u644A\u4F4D\uFF0C\u6CB3\u4E0A\u5546\u8D29\u4E0E\u4E61\u95F4\u4E70\u5BB6\u5728\u6B64\u4EA4\u6613\u3002"],["A modest market, in keeping with a river port.","\u4E00\u5904\u6734\u5B9E\u7684\u96C6\u5E02\uFF0C\u4E0E\u6CB3\u6E2F\u7684\u8EAB\u4EFD\u76F8\u79F0\u3002"],"low",["awoiaf"],["Stalls along the piers are mentioned; no market square is described.","\u6458\u8981\u63D0\u5230\u7801\u5934\u8FB9\u6709\u644A\u6863\uFF0C\u4F46\u6CA1\u6709\u63CF\u5199\u96C6\u5E02\u5E7F\u573A\u3002"],h,["A few awnings by the gate; no goods or people specified.","\u57CE\u95E8\u8FB9\u51E0\u9876\u906E\u7BF7\uFF1B\u4E0D\u6307\u660E\u8D27\u7269\u4E0E\u4EBA\u7269\u3002"])}};export{w as default};
